function normalize(p){const q=blank();if(!p||p.schema!==q.schema)return q;q.title=String(p.title??q.title).slice(0,200);q.objective=String(p.objective||'').slice(0,5000);q.inputRoute=['auto','raw_fastq','tagged_bam','count_matrix'].includes(p.inputRoute)?p.inputRoute:'auto';for(const[k,m]of [['stages','step'],['tools','tool'],['metrics','metric']])q[k]=[...new Set((Array.isArray(p[k])?p[k]:[]).filter(x=>api.maps()[m].has(x)))];q.projects=[...new Set((Array.isArray(p.projects)?p.projects:[]).filter(id=>projectCatalog().some(x=>x.id===id)))];q.resultSpecificationIds=[...new Set((Array.isArray(p.resultSpecificationIds)?p.resultSpecificationIds:[]).filter(id=>api.data().projects.resultSpecifications?.some(s=>s.id===id)))];q.markers=(Array.isArray(p.markers)?p.markers:[]).filter(x=>x&&api.maps().marker.has(x.id)).map(normalizeMarker);q.markers=q.markers.filter((x,i,a)=>a.findIndex(y=>y.id===x.id)===i);q.availableData=[...new Set((Array.isArray(p.availableData)?p.availableData:[]).map(x=>MIGRATION[x]||x).filter(x=>inventory().some(v=>v.id===x)))];q.edges=(Array.isArray(p.edges)?p.edges:[]).filter(x=>q.stages.includes(x.from)&&q.stages.includes(x.to)&&x.from!==x.to).map(x=>({from:x.from,to:x.to}));q.edges=q.edges.filter((x,i,a)=>a.findIndex(y=>y.from===x.from&&y.to===x.to)===i);if(hasCycle(q.edges))q.edges=[];for(const tool of Object.keys(p.parameters||{}).filter(id=>api.maps().tool.has(id))){const params=p.parameters?.[tool];if(params&&typeof params==='object'){q.parameters[tool]={};for(const [key,v]of Object.entries(params)){if(api.maps().tool.get(tool).parameters.some(x=>x.name===key))q.parameters[tool][key]=String(v).slice(0,2000);}}}return q;}
const snapshot=lab=>JSON.stringify(lab?{...plan,__recoveryLab:lab}:plan);
const content=x=>{const {updated,...rest}=typeof x==='string'?JSON.parse(x):x;return JSON.stringify(rest);};
function recoveryState(){return {...saveState,canUndo:history.length>0,canRedo:future.length>0,undoCount:history.length,redoCount:future.length,updated:plan?.updated||null};}
function publishState(){window.dispatchEvent(new CustomEvent('yv:planstate',{detail:recoveryState()}));}
function trimHistory(){while(history.length+future.length>HISTORY_LIMIT||(history.join('').length+future.join('').length)>HISTORY_CHARS){if(history.length>1)history.shift();else if(future.length)future.shift();else break;}}
function persistHistory(){trimHistory();try{localStorage.setItem(HISTORY_KEY,JSON.stringify({schema:'yv-plan-history/v1',current:content(plan),undo:history,redo:future}));saveState.historyPersisted=true;}catch{saveState.historyPersisted=false;}}
function restoreHistory(){try{const x=JSON.parse(localStorage.getItem(HISTORY_KEY));if(x?.schema!=='yv-plan-history/v1'||x.current!==content(plan))return;const valid=v=>typeof v==='string'&&JSON.parse(v)?.schema==='yeastvar1011-plan-v2';history=Array.isArray(x.undo)?x.undo.filter(valid):[];future=Array.isArray(x.redo)?x.redo.filter(valid):[];trimHistory();}catch{history=[];future=[];}}
function init(a){api=a;if(initialized)return;initialized=true;const old=load();plan=normalize(old);saveState.isDefaultTemplate=!old;if(!old)applyPreset('noise',false);else restoreHistory();api.syncMarkers(plan.markers.map(x=>x.id));save(false);}
function save(record=true){plan.updated=new Date().toISOString();try{try{localStorage.setItem(KEY,snapshot());}catch(error){if(!['QuotaExceededError','NS_ERROR_DOM_QUOTA_REACHED'].includes(error.name))throw error;try{localStorage.removeItem(HISTORY_KEY);}catch{}localStorage.setItem(KEY,snapshot());}saveState.status='saved';saveState.storageError=null;persistHistory();}catch(error){saveState.status='unsaved';saveState.storageError=error.name||'StorageError';saveState.historyPersisted=false;}publishState();if(record)window.dispatchEvent(new CustomEvent('yv:planchange'));return saveState.status==='saved';}
function mutate(fn,rerender=true){editSession=null;const before=snapshot();try{fn();}catch(error){plan=JSON.parse(before);throw error;}if(content(before)===content(plan))return false;history.push(before);future=[];saveState.isDefaultTemplate=false;trimHistory();save();api.syncMarkers(plan.markers.map(x=>x.id));if(rerender)api.render();return true;}
function restoreStep(from,to){if(!from.length)return false;editSession=null;const target=JSON.parse(from[from.length-1]),lab=target.__recoveryLab?window.YV_LAB.exportData():null;if(target.__recoveryLab)window.YV_LAB.importData(target.__recoveryLab,{merge:false});to.push(snapshot(lab));from.pop();plan=normalize(target);saveState.isDefaultTemplate=false;save();api.syncMarkers(plan.markers.map(x=>x.id));api.render();if(lab)api.toast(window.YV_RECOVERY?.text('restored')||b('importSuccess'));return true;}
function undo(){return restoreStep(history,future);}
function redo(){return restoreStep(future,history);}
function updateField(el){
 const field=el.dataset.planField,tid=el.dataset.toolId,param=el.dataset.planParam;
 if(field&&!['title','objective'].includes(field))return false;
 if(!field&&(!param||!api.maps().tool.get(tid)?.parameters.some(x=>x.name===param)))return false;
 const key=field?'field:'+field:'parameter:'+tid+':'+param,value=el.value.slice(0,field==='title'?200:field?5000:2000);
 const previous=field?plan[field]:plan.parameters[tid]?.[param];if(previous===value)return false;
 if(editSession!==key){history.push(snapshot());future=[];editSession=key;}
 if(field)plan[field]=value;else{plan.parameters[tid]||={};plan.parameters[tid][param]=value;if(!plan.tools.includes(tid)){plan.tools.push(tid);const target=api.maps().tool.get(tid).steps.find(s=>plan.stages.includes(s))||api.maps().tool.get(tid).steps[0];if(target&&!plan.stages.includes(target)){plan.stages.push(target);plan.metrics.push(...api.maps().step.get(target).metricIds.filter(x=>!plan.metrics.includes(x)));}}}
 saveState.isDefaultTemplate=false;trimHistory();save();return true;
}
function validateImport(value){
 if(!value||typeof value!=='object'||Array.isArray(value)||value.schema!=='yeastvar1011-plan-v2')throw Error('schema');
 for(const key of ['stages','tools','metrics','markers','edges','availableData'])if(!Array.isArray(value[key]))throw Error('shape');
 for(const key of ['projects','resultSpecificationIds'])if(value[key]!==undefined&&!Array.isArray(value[key]))throw Error('shape');
 for(const key of ['stages','tools','metrics','availableData','projects','resultSpecificationIds'])if(value[key]?.some(x=>typeof x!=='string'))throw Error('shape');
 for(const key of ['title','objective'])if(value[key]!==undefined&&typeof value[key]!=='string')throw Error('shape');
 if(value.parameters!==undefined&&(!value.parameters||typeof value.parameters!=='object'||Array.isArray(value.parameters)))throw Error('shape');
 if(value.markers.some(x=>!x||typeof x!=='object'||typeof x.id!=='string')||value.edges.some(x=>!x||typeof x.from!=='string'||typeof x.to!=='string'))throw Error('shape');
 return normalize(value);
}
function importPlan(value){const incoming=validateImport(value);if(value.extensions?.lab){if(!window.YV_LAB?.importData)throw Error('lab');const before=snapshot(window.YV_LAB.exportData());window.YV_LAB.importData(value.extensions.lab,{merge:true});editSession=null;history.push(before);future=[];plan=incoming;saveState.isDefaultTemplate=false;save();api.syncMarkers(plan.markers.map(x=>x.id));api.render();}else mutate(()=>{plan=incoming});return true;}
function backup(){const result=exported();if(window.YV_LAB?.exportData)result.extensions.lab=window.YV_LAB.exportData();api.download('YeastVar1011-plan-backup.json',JSON.stringify(result,null,2),'application/json;charset=utf-8');}
function applyPreset(type,rerender=true){const d=api.data().workflow;const stageSets={noise:d.steps.filter(s=>s.status==='core').map(s=>s.id),atlas:d.steps.filter(s=>s.status==='core'&&!['noise','validation'].includes(s.id)).map(s=>s.id),dynamics:[...d.steps.filter(s=>s.status==='core').map(s=>s.id),'dynamics','transcripts'],genetics:d.steps.map(s=>s.id)};const favorites=['seqkit','fastqc','multiqc','umitools','starsolo','samtools','rseqc','dropletutils','soupx','scdblfinder','scuttle','scater','scanpy','ucell','edger','fgsea','memento','glmmtmb','scdesign3'];if(type==='dynamics')favorites.push('velocyto','scvelo','slingshot');if(type==='genetics')favorites.push('gemma','susie','coloc','inferelator');const update=()=>{plan.stages=[...new Set(stageSets[type]||stageSets.noise)].sort((a,b)=>api.maps().step.get(a).number-api.maps().step.get(b).number);plan.tools=favorites.filter(x=>api.maps().tool.has(x)&&api.maps().tool.get(x).steps.some(s=>plan.stages.includes(s)));plan.metrics=[...new Set(plan.stages.flatMap(s=>api.maps().step.get(s).metricIds))];plan.edges=plan.stages.slice(1).map((s,i)=>({from:plan.stages[i],to:s}));plan.parameters={};plan.projects=[];ui.stage=plan.stages[1]||plan.stages[0];if(plan.inputRoute!=='auto'||window.YV_INPUTS.route(plan)!=='raw_fastq')window.YV_INPUTS.applyRoute?.(plan,plan.inputRoute,api.data());};if(rerender)mutate(update);else update();}
function setResultSpecification(id,checked,rerender=false){if(!api.data().projects.resultSpecifications?.some(s=>s.id===id))return false;mutate(()=>{plan.resultSpecificationIds=checked?[...new Set([...(plan.resultSpecificationIds||[]),id])]:(plan.resultSpecificationIds||[]).filter(v=>v!==id);},rerender);return true;}
function setMarkers(markerIds,checked,rerender=false){
 const ids=[...new Set((Array.isArray(markerIds)?markerIds:[]).filter(id=>api?.maps().marker.has(id)))];
 if(!ids.length)return false;
 mutate(()=>{if(checked){for(const id of ids)if(!plan.markers.some(m=>m.id===id))plan.markers.push(normalizeMarker({id,groups:['unassigned'],purposes:[ui.purpose]}));}else plan.markers=plan.markers.filter(m=>!ids.includes(m.id));},rerender);return true;
}
function importMarkerAssignments(assignments,{merge=true,rerender=false}={}){
 if(!Array.isArray(assignments))return false;
 const seen=new Set(),allowed=['groups','purpose','purposes','role','userTags','rationale','evidenceSources','evidenceIds'];
 for(const row of assignments)if(row&&typeof row==='object')window.YV_MARKER_SELECTION.normalizeField(row);
 const rows=assignments.filter(row=>{if(!row||typeof row!=='object'||!api?.maps().marker.has(row.id)||seen.has(row.id))return false;seen.add(row.id);return true;});
 if(!rows.length&&merge)return false;
 // A panel import is one user operation, like importPlan: one snapshot, one
 // persistence pass, and one undo. Omitted assignments retain existing choices.
 return mutate(()=>{
  const previous=new Map(plan.markers.map(marker=>[marker.id,marker]));
  const next=merge?[...plan.markers]:[],positions=new Map(next.map((marker,i)=>[marker.id,i]));
  for(const row of rows){
   const base=previous.get(row.id)||{id:row.id,groups:['unassigned'],purposes:[ui.purpose]};
   const patch=Object.fromEntries(allowed.filter(key=>Object.hasOwn(row,key)).map(key=>[key,row[key]]));
   if(Object.hasOwn(patch,'purpose')&&!Object.hasOwn(patch,'purposes'))patch.purposes=undefined;
   const marker=normalizeMarker({...base,...patch,id:row.id});
   if(positions.has(row.id))next[positions.get(row.id)]=marker;
   else{positions.set(row.id,next.length);next.push(marker);}
  }
  plan.markers=next;
 },rerender);
}
function setMarker(markerId,checked,group){
 if(!api)return;const exists=plan.markers.some(x=>x.id===markerId);
 if(checked&&!exists&&api.maps().marker.has(markerId)){mutate(()=>plan.markers.push(normalizeMarker({id:markerId,groups:group&&GROUPS.includes(group)?[group]:['unassigned'],purposes:[ui.purpose]})),false);}
 else if(!checked&&exists)setMarkers([markerId],false,false);
}
function updateMarkers(markerIds,patch,rerender=false){
 const ids=[...new Set((Array.isArray(markerIds)?markerIds:[]).filter(id=>api?.maps().marker.has(id)))];
 if(!ids.length||!patch||typeof patch!=='object')return false;
 const allowed=['groups','purpose','purposes','role','userTags','rationale','evidenceSources','evidenceIds'];
 window.YV_MARKER_SELECTION.normalizeField(patch);
 const clean=Object.fromEntries(Object.entries(patch).filter(([key])=>allowed.includes(key)));
 mutate(()=>{for(const id of ids){const index=plan.markers.findIndex(x=>x.id===id),previous=index<0?{id,groups:['unassigned'],purposes:[ui.purpose]}:plan.markers[index];const next=normalizeMarker({...previous,...clean,id});if(index<0)plan.markers.push(next);else plan.markers[index]=next;}},rerender);return true;
}
function updateMarker(markerId,patch,rerender=false){return updateMarkers([markerId],patch,rerender);}
function assignMarker(markerId,group){
 if(!api.maps().marker.has(markerId)||!GROUPS.includes(group))return;
 const existing=plan.markers.find(x=>x.id===markerId);updateMarker(markerId,{groups:[...new Set([...(existing?.groups||[]).filter(g=>g!=='unassigned'),group])]},true);
}
function toggleTool(toolId,checked){if(!api.maps().tool.has(toolId))return;mutate(()=>{if(checked){if(!plan.tools.includes(toolId))plan.tools.push(toolId);const target=api.maps().tool.get(toolId).steps.find(s=>plan.stages.includes(s))||api.maps().tool.get(toolId).steps[0];if(target&&!plan.stages.includes(target)){plan.stages.push(target);plan.metrics.push(...api.maps().step.get(target).metricIds.filter(x=>!plan.metrics.includes(x)));}}else plan.tools=plan.tools.filter(x=>x!==toolId);},false);}
function toggleMetric(metricId,checked){const metric=api?.maps().metric.get(metricId);if(!metric)return false;mutate(()=>{if(checked){if(!plan.metrics.includes(metricId))plan.metrics.push(metricId);if(api.maps().step.has(metric.stepId)&&!plan.stages.includes(metric.stepId)){plan.stages.push(metric.stepId);plan.stages.sort((a,b)=>api.maps().step.get(a).number-api.maps().step.get(b).number);}}else plan.metrics=plan.metrics.filter(x=>x!==metricId);},false);updateBadge();return true;}
function setInputRoute(route){if(!['auto','raw_fastq','tagged_bam','count_matrix'].includes(route))return false;mutate(()=>{if(window.YV_INPUTS.applyRoute)window.YV_INPUTS.applyRoute(plan,route,api.data());else plan.inputRoute=route;},false);return true;}
function setMetrics(ids,checked,rerender=false){const valid=[...new Set(ids)].filter(id=>api.maps().metric.has(id));mutate(()=>{if(checked){plan.metrics=[...new Set([...plan.metrics,...valid])];plan.stages=[...new Set([...plan.stages,...valid.map(id=>api.maps().metric.get(id).stepId)])].sort((a,b)=>api.maps().step.get(a).number-api.maps().step.get(b).number);}else plan.metrics=plan.metrics.filter(id=>!valid.includes(id));},rerender);return true;}
function setProjects(ids){const valid=[...new Set(ids.filter(id=>projectCatalog().some(p=>p.id===id)))];mutate(()=>{const added=valid.filter(id=>!plan.projects.includes(id)).map(id=>projectCatalog().find(p=>p.id===id));plan.projects=valid;for(const p of added){plan.stages=[...new Set([...plan.stages,...p.stepIds.filter(id=>api.maps().step.has(id))])];plan.tools=[...new Set([...plan.tools,...p.toolIds.filter(id=>api.maps().tool.has(id))])];plan.metrics=[...new Set([...plan.metrics,...p.metricIds.filter(id=>api.maps().metric.has(id))])];}plan.stages.sort((a,b)=>api.maps().step.get(a).number-api.maps().step.get(b).number);if(plan.inputRoute!=='auto'||window.YV_INPUTS.route(plan)!=='raw_fastq')window.YV_INPUTS.applyRoute?.(plan,plan.inputRoute,api.data());},false);}
function addProject(projectId){const project=projectCatalog().find(x=>x.id===projectId);if(!project)return false;mutate(()=>{plan.projects||=[];if(!plan.projects.includes(projectId))plan.projects.push(projectId);plan.stages=[...new Set([...plan.stages,...project.stepIds.filter(id=>api.maps().step.has(id))])].sort((a,b)=>api.maps().step.get(a).number-api.maps().step.get(b).number);plan.tools=[...new Set([...plan.tools,...project.toolIds.filter(id=>api.maps().tool.has(id))])];plan.metrics=[...new Set([...plan.metrics,...project.metricIds.filter(id=>api.maps().metric.has(id))])];if(!plan.stages.includes(ui.stage))ui.stage=plan.stages[0]||'fastq';if(plan.inputRoute!=='auto'||window.YV_INPUTS.route(plan)!=='raw_fastq')window.YV_INPUTS.applyRoute?.(plan,plan.inputRoute,api.data());});return true;}
function toggleStage(stageId,checked){mutate(()=>{if(checked){if(!plan.stages.includes(stageId))plan.stages.push(stageId);plan.metrics.push(...api.maps().step.get(stageId).metricIds.filter(x=>!plan.metrics.includes(x)));}else{plan.stages=plan.stages.filter(x=>x!==stageId);plan.edges=plan.edges.filter(x=>x.from!==stageId&&x.to!==stageId);plan.metrics=plan.metrics.filter(x=>api.maps().metric.get(x).stepId!==stageId);plan.tools=plan.tools.filter(x=>api.maps().tool.get(x).steps.some(s=>plan.stages.includes(s)));}if(!plan.stages.includes(ui.stage))ui.stage=plan.stages[0]||'fastq';});}
function hasCycle(edges){const graph=new Map();edges.forEach(({from,to})=>graph.set(from,[...(graph.get(from)||[]),to]));const visiting=new Set(),done=new Set();const visit=v=>{if(visiting.has(v))return true;if(done.has(v))return false;visiting.add(v);for(const n of graph.get(v)||[])if(visit(n))return true;visiting.delete(v);done.add(v);return false;};return [...graph.keys()].some(visit);}
function missingStages(){return [...new Set(plan.stages.flatMap(s=>(window.YV_INPUTS.stageDependencies?.(plan,api.data(),s)||DEPENDENCIES[s]||[]).filter(x=>!plan.stages.includes(x))))];}
function prerequisiteClosure(){const result=new Set(plan.stages);let changed=true;while(changed){changed=false;for(const s of [...result])for(const dep of window.YV_INPUTS.stageDependencies?.(plan,api.data(),s)||DEPENDENCIES[s]||[])if(!result.has(dep)){result.add(dep);changed=true;}}return [...result].sort((a,b)=>api.maps().step.get(a).number-api.maps().step.get(b).number);}
