function neededInputs(){return inputReview().inputs.filter(x=>!['declared','planned-output','conditional-output'].includes(x.status)).map(x=>x.id);}
function inputReviewHTML(){const result=inputReview();return `<p class="muted small">${b('inputReviewHelp')}</p><div class="input-review-list">${result.inputs.map(x=>`<div class="input-review-row"><div><strong>${e(inputLabel(x.id))}</strong><span class="badge ${x.status==='declared'?'badge-green':'badge-amber'}">${b(x.status)}</span></div>${x.producerTools.length?`<small>${b('plannedProducer')}: ${x.producerTools.map(id=>e(api.maps().tool.get(id)?.name||id)).join(' '+e(window.YV_PLAN?.text?.('methodOr')||'/')+' ')}</small>`:''}${x.dependencies.length?`<small>${tt('inputs')}: ${x.dependencies.map(k=>e(inputLabel(k))).join(' · ')}</small>`:''}${x.unresolved.length?`<small>${b('upstreamPending')}: ${x.unresolved.map(k=>e(inputLabel(k))).join(' · ')}</small>`:''}${window.YV_PLAN?.inputRoutesHTML?.(x)||''}</div>`).join('')}</div>${result.rules.length?`<h3>${b('compatibility')}</h3>${api.list(result.rules.map(r=>r.text))}`:''}`;}
const btn=(action,text,attrs='',cls='btn btn-small')=>`<button class="${cls}" data-build="${action}" ${attrs}>${text}</button>`;
const stepTitle = id=>api.field('steps',api.maps().step.get(id),'title');
const metricTitle = id=>api.field('metrics',api.maps().metric.get(id),'name');
const count =()=>`<div class="plan-counts"><span><b>${plan.stages.length}</b>${tt('steps')}</span><span><b>${plan.tools.length}</b>${tt('tools')}</span><span><b>${plan.metrics.length}</b>${tt('metrics')}</span><span><b>${plan.markers.length}</b>${tt('genes')}</span></div>`;
function page(a){init(a);return `<div class="builder-heading"><div><div class="eyebrow">YEASTVAR1011 / ${b('researchDesign')}</div><h1>${b('builder')}</h1><p>${b('planningOnly')}</p></div><div class="builder-actions">${window.YV_RECOVERY?.markup()||''}${btn('import',api.icon('download')+' '+b('importPlan'))}<input type="file" id="plan-import" accept=".json,application/json" hidden></div></div><div class="builder-stepper">${['scope','studio','assemble','review'].map((key,i)=>btn('tab',`<span class="builder-step-number">0${i+1}</span><span><strong>${b(key)}</strong><small>${[b('objective'),b('assigned'),b('chosenTools'),b('exportPlan')][i]}</small></span>${api.icon('arrow')}`,`data-value="${key}" aria-current="${ui.tab===key?'step':'false'}"`,`builder-step ${ui.tab===key?'active':''}`)).join('')}</div>${ui.tab==='scope'?scopePage():ui.tab==='studio'?studioPage():ui.tab==='assemble'?assemblePage():reviewPage()}<div class="builder-bottom"><span>${b('sourceIntact')} · ${b('sourcesExported')}</span>${count()}${ui.tab!=='review'?btn('next',tt('next')+' '+api.icon('arrow'),'','btn btn-primary'):''}</div>`;}
function scopePage(){const cats=api.data().categories?.categories||[];return `${window.YV_V3?.selectedProjects()||''}<div class="scope-grid"><section class="panel scope-form"><div class="section-head"><h2>${b('scope')}</h2><span class="badge badge-green">1011 · S. cerevisiae</span></div><p class="muted">${b('scopeBody')}</p><label class="plan-field">${b('name')}<input data-plan-field="title" value="${e(plan.title)}" maxlength="200"></label><label class="plan-field">${b('objective')}<textarea data-plan-field="objective" rows="4" placeholder="${e(b('objectiveHint'))}">${e(plan.objective)}</textarea></label><div class="section-head"><h3>${b('available')}</h3><span class="small muted">${b('dataNotExecution')}</span></div><p class="muted small">${b('inputHelp')}</p><div class="inventory-grid">${inventory().map(x=>`<label class="inventory-item ${plan.availableData.includes(x.id)?'checked':''}" title="${e(tx(x.description))}"><input type="checkbox" data-inventory="${x.id}" ${plan.availableData.includes(x.id)?'checked':''}><span>${e(inputLabel(x.id))}</span></label>`).join('')}</div></section><aside><div class="section-head"><h2>${b('templates')}</h2></div><p class="muted small">${b('templateHelp')}</p><div class="preset-list">${[['noise','presetNoise','chart','01'],['atlas','presetAtlas','markers','02'],['dynamics','presetDynamics','clock','03'],['genetics','presetGenetics','ideas','04']].map(([key,label,ic,n])=>`<button class="preset-card" data-build="preset" data-value="${key}"><span class="preset-icon">${api.icon(ic)}</span><span><small>${n} / ${b(label)}</small><strong>${b(label)}</strong><em>${b('useTemplate')} →</em></span></button>`).join('')}</div><div class="planning-card"><img src="assets/yeastvar-emblem.png" alt="" width="76" height="76"><h3>${b('workbench')}</h3><p>${b('planningOnly')}</p></div></aside></div>${cats.length?`<div class="section-head"><h2>${b('researchCategories')}</h2><span class="muted small">${b('methodsByPurpose')}</span></div><div class="research-category-grid">${cats.map(c=>`<a href="#tools?category=${e(c.id)}" class="research-category-card"><span class="badge">${(c.toolIds||[]).length} ${tt('tools')}</span><h3>${e(categoryText(c,'title'))}</h3><p>${e(categoryText(c,'description'))}</p>${api.icon('arrow')}</a>`).join('')}</div>`:''}`;}
function categoryText(c,key){if(api.prefs().language==='zh')return c[key];return window.YV_CATEGORY_LOCALES?.[c.id]?.[api.prefs().language]?.[key]||(tx(c[key])!==c[key]?tx(c[key]):c[key+'En']||c[key]);}
function phaseSelector(){return `<div class="studio-phases">${PHASES.map((p,i)=>btn('phase',`<span class="phase-dot phase-${i}"></span>${p}`,`data-value="${p}" aria-pressed="${activePhase===p}"`,`phase-tab ${activePhase===p?'active':''}`)).join('')}</div>`;}
function studioPage(){return `<div class="studio-intro"><div><h2>${b('modelCells')}</h2><p>${b('phaseHelp')}</p></div><a class="text-link" href="#markers">${tt('markers')} ↗</a></div><div class="cycle-workspace"><aside class="candidate-panel panel"><div class="panel-heading"><h3>${b('candidates')}</h3><span id="phase-candidate-count"></span></div><div class="candidate-controls"><label class="search-field">${api.icon('search')}<input type="search" id="studio-marker-query" placeholder="${b('geneQuery')}" value="${e(ui.markerQ)}" aria-label="${tt('search')}"></label><label class="check-row"><input type="checkbox" id="studio-only-chosen" ${ui.onlyChosen?'checked':''}>${b('showAssigned')}</label></div><div id="studio-candidates" class="candidate-list">${candidateRows()}</div><a href="#markers" class="candidate-footer">${tt('viewAll')} ${api.data().markers.markers.length} ${tt('genes')} →</a></aside><section class="cycle-center panel"><div class="cycle-center-top"><span class="badge badge-green">S. cerevisiae</span><span id="studio-phase-name">${activePhase}</span>${btn('rotate',api.icon('clock'),`title="${b(paused?'resume':'pause')}" aria-label="${b(paused?'resume':'pause')}"`,'icon-btn')}</div><div id="cycle-model" class="yeast-scene" aria-label="${e(b('schematic3d'))}"></div><div class="scene-foot"><span>${b('dragHint')}</span><small>${b('schematic3d')}</small></div>${phaseSelector()}<div class="cycle-caption"><span>${b('phaseRNA')}: <b id="active-rna-phase">${activePhase}</b></span><span>${b('sourceIntact')}</span></div></section><aside class="assignment-panel panel"><div class="panel-heading"><h3>${b('assigned')}</h3><span>${plan.markers.length} ${tt('genes')}</span></div><div class="assignment-settings"><label>${b('purpose')}<select id="marker-purpose">${PURPOSES.map(p=>`<option value="${p}" ${ui.purpose===p?'selected':''}>${b(p)}</option>`).join('')}</select></label><label>${b('destination')}<select id="marker-destination">${GROUPS.map(g=>`<option value="${g}" ${ui.destination===g?'selected':''}>${groupLabel(g)}</option>`).join('')}</select></label></div><p class="assignment-help">${b('assignmentHelp')}</p><div id="assignment-groups" class="assignment-groups">${groupCards()}</div></aside></div>`;}
function candidateRows(){const q=ui.markerQ.toLowerCase();const rows=api.data().markers.markers.filter(m=>(ui.onlyChosen?plan.markers.some(x=>x.id===m.id):q?true:m.phases.includes(activePhase))&&(!q||m._search.includes(q))).sort((a,b)=>Number(!!b.seed)-Number(!!a.seed)||a.symbol.localeCompare(b.symbol));setTimeout(()=>{const el=$('#phase-candidate-count');if(el)el.textContent=rows.length+' '+tt('genes')},0);return (rows.slice(0,ui.markerLimit).map(m=>`<div class="candidate-row ${plan.markers.some(x=>x.id===m.id)?'chosen':''}" draggable="true" data-drag-marker="${m.id}"><span class="drag-handle" aria-hidden="true">⠿</span><label><input type="checkbox" data-studio-marker="${m.id}" ${plan.markers.some(x=>x.id===m.id)?'checked':''} aria-label="${tt('select')} ${e(m.symbol)}"></label><button data-build="marker-info" data-id="${m.id}" class="candidate-gene"><strong>${e(m.symbol)}</strong><small>${e(m.systematic)}</small></button><span class="candidate-grades">${api.grades(m)}</span><span class="candidate-phase">${e(m.phases.join(' / ')||'—')}</span></div>`).join('')||`<div class="empty-state"><p>${tt('noResults')}</p></div>`)+(rows.length>ui.markerLimit?btn('more-markers',b('loadMore')+` (${Math.min(ui.markerLimit,rows.length)}/${rows.length})`,'','btn marker-load-more'):'');}
function groupCards(){return GROUPS.map(g=>{const items=plan.markers.filter(x=>x.groups.includes(g));return `<div class="marker-group ${g===activePhase?'phase-current':''}" data-drop-group="${g}"><div class="marker-group-head"><strong>${groupLabel(g)}</strong><span>${items.length}</span></div>${items.length?`<div class="group-markers">${items.map(x=>{const m=api.maps().marker.get(x.id);return `<div class="assigned-marker" draggable="true" data-drag-marker="${m.id}"><button data-build="marker-info" data-id="${m.id}" title="${e((x.purposes||[x.purpose]).map(b).join(' · '))}">${e(m.symbol)}<small>${(x.purposes||[x.purpose]).map(b).join(' · ')}</small></button><select data-marker-purpose="${m.id}" aria-label="${e(m.symbol)} · ${b('purpose')}">${PURPOSES.map(p=>`<option value="${p}" ${x.purpose===p?'selected':''}>${b(p)}</option>`).join('')}</select>${btn('remove-group','×',`data-id="${m.id}" data-group="${g}" aria-label="${b('removeGroup')}"`,'remove-marker')}</div>`}).join('')}</div>`:`<span class="drop-hint">${b('dropHere')}</span>`}</div>`}).join('');}
function updateStudio(){if($('#studio-candidates'))$('#studio-candidates').innerHTML=candidateRows();if($('#assignment-groups'))$('#assignment-groups').innerHTML=groupCards();document.querySelectorAll('.phase-tab').forEach(el=>{el.classList.toggle('active',el.dataset.value===activePhase);el.setAttribute('aria-pressed',el.dataset.value===activePhase)});for(const id of ['studio-phase-name','active-rna-phase'])if($('#'+id))$('#'+id).textContent=activePhase;if($('#marker-destination'))$('#marker-destination').value=ui.destination;cell?.setPhase(activePhase);document.querySelectorAll('.plan-counts').forEach(el=>{const box=document.createElement('div');box.innerHTML=count();el.innerHTML=box.firstElementChild.innerHTML});const n=document.querySelector('.assignment-panel .panel-heading>span');if(n)n.textContent=plan.markers.length+' '+tt('genes');}
function assemblePage(){const s=api.maps().step.get(ui.stage)||api.maps().step.get('fastq');return `<div class="assemble-intro"><div><h2>${b('assemble')}</h2><p>${b('dragStages')}</p></div>${btn('auto-connect',api.icon('workflow')+' '+b('autoConnect'))}</div><div class="assembly-grid"><aside class="stage-picker panel"><div class="panel-heading"><h3>${b('stageLibrary')}</h3><span>${plan.stages.length}/20</span></div>${api.data().workflow.steps.map(x=>`<label class="stage-choice ${plan.stages.includes(x.id)?'checked':''}"><input type="checkbox" data-plan-stage="${x.id}" ${plan.stages.includes(x.id)?'checked':''}><span class="mono">${String(x.number).padStart(2,'0')}</span><span>${e(api.field('steps',x,'title'))}<small>${tt(x.status)}</small></span></label>`).join('')}</aside><section class="workflow-canvas" id="workflow-canvas"><svg id="connection-svg" aria-hidden="true"></svg>${plan.stages.length?plan.stages.map((sid,i)=>{const s=api.maps().step.get(sid),tools=plan.tools.filter(id=>api.maps().tool.get(id).steps.includes(sid)),metrics=plan.metrics.filter(id=>api.maps().metric.get(id).stepId===sid);return `<article class="plan-node ${ui.stage===sid?'focused':''} ${ui.connectFrom===sid?'connecting':''}" data-node="${sid}" data-drop-stage="${sid}"><button class="node-port node-input" data-build="input" data-id="${sid}" aria-label="${e(b('inputPort')+' '+stepTitle(sid))}" title="${b('inputPort')}"></button><div class="node-head" draggable="true" data-drag-stage="${sid}"><span class="drag-handle">⠿</span><span class="node-index">${String(i+1).padStart(2,'0')}</span><button class="node-title" data-build="focus-stage" data-id="${sid}"><strong>${e(stepTitle(sid))}</strong><small>${e(api.field('steps',s,'subtitle'))}</small></button><div class="node-reorder">${btn('move','↑',`data-id="${sid}" data-direction="-1" aria-label="${b('moveUp')}" ${i===0?'disabled':''}`,'icon-btn')}${btn('move','↓',`data-id="${sid}" data-direction="1" aria-label="${b('moveDown')}" ${i===plan.stages.length-1?'disabled':''}`,'icon-btn')}</div></div><div class="node-tools">${tools.length?tools.map(id=>`<button class="tool-pill" data-build="tool-info" data-id="${id}">${e(api.maps().tool.get(id).name)}</button>`).join(''):`<button class="node-empty" data-build="focus-stage" data-id="${sid}">+ ${b('noTools')}</button>`}</div><div class="node-meta"><span>${metrics.length} ${tt('metrics')} · ${s.formulaIds.length} ${tt('formulas')}</span><span class="badge ${s.status==='core'?'badge-green':'badge-amber'}">${tt(s.status)}</span></div><button class="node-port node-output" data-build="output" data-id="${sid}" aria-label="${e(b('outputPort')+' '+stepTitle(sid))}" title="${b('outputPort')}"></button></article>`}).join(''):`<div class="empty-state">${b('noSteps')}</div>`}</section><aside class="tool-picker panel"><div class="panel-heading"><h3>${b('toolLibrary')}</h3><span>${e(stepTitle(s.id))}</span></div><div class="picker-tabs">${['tools','metrics'].map(k=>btn('tool-tab',tt(k),`data-value="${k}"`,ui.toolTab===k?'active':'')).join('')}</div><div class="picker-search"><input id="plan-tool-search" type="search" value="${e(ui.query)}" placeholder="${tt('search')}" aria-label="${tt('search')}"></div><div id="picker-results" class="picker-results">${pickerResults()}</div><div class="connector-status">${ui.connectFrom?`${api.icon('workflow')}<strong>${b('connecting')}</strong><span>${e(stepTitle(ui.connectFrom))}</span>${btn('cancel-connect',tt('close'),'','text-link')}`:`<span>${b('connections')}: ${plan.edges.length}</span>`}</div><details class="edge-list"><summary>${b('connections')}</summary>${plan.edges.map((ed,i)=>`<div><span>${e(stepTitle(ed.from))} → ${e(stepTitle(ed.to))}</span>${btn('remove-edge','×',`data-index="${i}" aria-label="${tt('clear')}"`,'icon-btn')}</div>`).join('')}</details></aside></div>`;}
function pickerResults(){const q=ui.query.toLowerCase(),s=api.maps().step.get(ui.stage);if(!s)return '';if(ui.toolTab==='metrics')return s.metricIds.map(id=>api.maps().metric.get(id)).filter(x=>!q||(x._search||JSON.stringify(x)).toLowerCase().includes(q)).map(m=>`<label class="picker-item"><input type="checkbox" data-plan-metric="${m.id}" ${plan.metrics.includes(m.id)?'checked':''}><span><strong>${e(api.field('metrics',m,'name'))}</strong><small>${e(api.field('metrics',m,'definition'))}</small></span></label>`).join('');return api.data().workflow.tools.filter(x=>x.steps.includes(s.id)&&(!q||(x._search||JSON.stringify(x)).toLowerCase().includes(q))).map(x=>`<div class="picker-item" draggable="true" data-drag-tool="${x.id}"><input type="checkbox" data-plan-tool="${x.id}" ${plan.tools.includes(x.id)?'checked':''} aria-label="${b('add')} ${e(x.name)}"><span><button data-build="tool-info" data-id="${x.id}"><strong>${e(x.name)}</strong></button><small>${e(api.field('tools',x,'task'))}</small><em>${b(x.applicability?.level||'adapt')}</em></span></div>`).join('')||`<div class="empty-state">${tt('noResults')}</div>`;}
function reviewPage(){const gaps=missingStages(),inputs=neededInputs(),unknown=plan.tools.flatMap(id=>api.maps().tool.get(id).parameters.filter(p=>p.required&&!plan.parameters[id]?.[p.name]?.trim()).map(p=>({tool:id,name:p.name})));return `${window.YV_V3?.selectedProjects()||''}<section class="review-hero"><div><div class="eyebrow">${b('blueprint')}</div><h2>${e(plan.title)}</h2><p>${e(plan.objective||b('objectiveHint'))}</p><small>${b('reviewBody')}</small></div><div class="review-emblem"><img src="assets/yeastvar-emblem.png" alt="" width="180" height="180"></div></section><div class="review-stat-grid">${[[plan.stages.length,tt('steps')],[plan.tools.length,tt('tools')],[plan.markers.length,tt('genes')],[unknown.length,b('unconfirmed')+' '+tt('parameters')]].map(([n,label])=>`<div><strong>${n}</strong><span>${label}</span></div>`).join('')}</div>${window.YV_MARKERS?.reviewPanel?.(plan)||''}<div class="review-grid"><section><div class="panel review-panel"><div class="section-head"><h3>${b('dependencies')}</h3>${gaps.length?btn('repair',b('addDependencies')):''}</div>${gaps.length?`<div class="gap-list">${gaps.map(id=>`<span class="badge badge-amber">${e(stepTitle(id))}</span>`).join('')}</div>`:`<p class="success-line">${api.icon('check')} ${b('noGaps')}</p>`}<p class="muted small">${b('notVerified')}</p><h3>${b('requiredData')}</h3>${inputReviewHTML()}<h3>${b('parameters')}</h3><p class="muted small">${b('parameterHint')}</p><div class="parameter-decision-list">${plan.tools.map(id=>{const tool=api.maps().tool.get(id),n=Object.values(plan.parameters[id]||{}).filter(Boolean).length;return `<button data-build="tool-info" data-id="${id}"><strong>${e(tool.name)}</strong><span>${n} ${b('overrides')} →</span></button>`}).join('')}</div></div><div class="panel review-panel"><div class="section-head"><h3>${b('workflowPreview')}</h3><span>${plan.edges.length} ${b('connections')}</span></div>${plan.stages.map((id,i)=>`<div class="review-stage"><span>${String(i+1).padStart(2,'0')}</span><div><strong>${e(stepTitle(id))}</strong><p>${plan.tools.filter(t=>api.maps().tool.get(t).steps.includes(id)).map(t=>e(api.maps().tool.get(t).name)).join(' · ')||b('noTools')}</p></div></div>`).join('')}</div></section><aside><div class="export-card"><div class="eyebrow">${b('exportKicker')}</div><h2>${b('exportPlan')}</h2><p>${b('sourcesExported')}</p>${window.YV_V3?.exportActions()||''}${btn('export-md',api.icon('download')+' '+b('exportMarkdown'),'','btn btn-primary')}${btn('export-json',api.icon('download')+' '+b('exportJSON'),'','btn')}${btn('export-svg',api.icon('workflow')+' SVG · '+b('exportGraph'),'','btn')}${btn('export-mermaid','Mermaid · '+b('exportGraph'),'','btn')}<small>${b('planningOnly')}</small></div><div class="panel review-panel"><h3>${b('chosenMarkers')}</h3><p class="muted small">${b('groupWarning')}</p>${GROUPS.filter(g=>plan.markers.some(m=>m.groups.includes(g))).map(g=>`<div class="review-marker-group"><strong>${groupLabel(g)}</strong><p>${plan.markers.filter(m=>m.groups.includes(g)).map(m=>e(api.maps().marker.get(m.id).symbol)).join(' · ')}</p></div>`).join('')||`<p class="muted small">${b('noMarkers')}</p>`}</div><div class="panel review-panel"><h3>${b('portability')}</h3>${plan.tools.filter(id=>api.maps().tool.get(id).applicability?.level&&api.maps().tool.get(id).applicability.level!=='ready').map(id=>{const x=api.maps().tool.get(id);return `<div class="review-marker-group"><button data-build="tool-info" data-id="${id}"><strong>${e(x.name)}</strong></button><p>${b(x.applicability.level)}</p></div>`}).join('')}</div></aside></div>`;}
function drawEdges(){const host=$('#workflow-canvas'),svg=$('#connection-svg');if(!host||!svg)return;const rect=host.getBoundingClientRect();svg.setAttribute('viewBox',`0 0 ${host.clientWidth} ${host.scrollHeight}`);svg.setAttribute('width',host.clientWidth);svg.setAttribute('height',host.scrollHeight);svg.innerHTML=`<defs><marker id="edge-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="currentColor"/></marker></defs>`+plan.edges.map(({from,to})=>{const a=host.querySelector(`[data-node="${from}"] .node-output`),z=host.querySelector(`[data-node="${to}"] .node-input`);if(!a||!z)return '';const ar=a.getBoundingClientRect(),zr=z.getBoundingClientRect(),x=ar.left+ar.width/2-rect.left,y=ar.top+ar.height/2-rect.top+host.scrollTop,xx=zr.left+zr.width/2-rect.left,yy=zr.top+zr.height/2-rect.top+host.scrollTop;const detour=yy<y?Math.min(host.clientWidth-7,x+185):x;return `<path d="M${x},${y} C${detour},${y+34} ${detour},${yy-34} ${xx},${yy}" marker-end="url(#edge-arrow)"/>`;}).join('');}
function wantedSceneId(){return api?.route()==='overview'?'home-yeast-scene':api?.route()==='builder'&&ui.tab==='studio'?'cycle-model':null;}
function sceneLabels(){return {ariaLabel:b('schematic3d'),fallback:b('fallback'),schematic:''};}
function reducedSceneMotion(){return !!api?.prefs().reducedMotion||!!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;}
function syncScene(){if(!cell)return;cell.setLabels?.(sceneLabels());cell.setPhase?.(activePhase);cell.setTheme?.(document.documentElement.dataset.theme);cell.setReducedMotion?.(reducedSceneMotion());cell.setMotion?.(!paused);cell.setPaused?.(paused);cell.resize?.();}
function destroyScene(){if(sceneReadyHandler)window.removeEventListener('yv3d:ready',sceneReadyHandler);sceneReadyHandler=null;cell?.destroy();cell=null;sceneNode=null;sceneId=null;}
function fallbackScene(container){let phase=activePhase,theme=document.documentElement.dataset.theme,labels=sceneLabels();const host=document.createElement('div');host.className='yv3d-stage';host.dataset.mode='fallback';container.append(host);const draw=()=>{host.dataset.phase=phase;host.dataset.theme=theme;const n=Math.max(0,PHASES.indexOf(phase)),bud=n===0?0:n===1?24:n===2?35:n===3?46:n===4?57:66,dark=theme==='dark',fill=dark?'#52a996':'#73b6a3',line=dark?'#d4ede1':'#315f50';host.innerHTML=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 500 380" role="img" aria-label="${e(labels.ariaLabel)}" style="width:100%;height:100%;max-height:440px"><ellipse cx="238" cy="340" rx="130" ry="15" fill="${line}" opacity=".12"/><ellipse cx="220" cy="210" rx="91" ry="116" fill="${fill}" fill-opacity=".3" stroke="${line}" stroke-width="3"/>${bud?`<ellipse cx="${phase==='M/G1'?355:314}" cy="${phase==='M/G1'?163:130}" rx="${bud}" ry="${bud*1.15}" fill="${fill}" fill-opacity=".3" stroke="${line}" stroke-width="3"/>`:''}<ellipse cx="219" cy="202" rx="30" ry="34" fill="#bcb3dd" fill-opacity=".65" stroke="${line}" stroke-width="2"/>${n>=4?`<ellipse cx="${phase==='M/G1'?353:304}" cy="${phase==='M/G1'?164:139}" rx="19" ry="22" fill="#bcb3dd" fill-opacity=".65" stroke="${line}" stroke-width="2"/>`:''}<ellipse cx="182" cy="255" rx="25" ry="35" fill="#e8cf94" fill-opacity=".5"/><text x="250" y="365" text-anchor="middle" fill="${line}" font-family="sans-serif" font-size="13">${e(phase)} · ${e(labels.fallback)}</text></svg>`;};draw();return {setPhase:p=>{phase=p;draw();},setTheme:t=>{theme=t;draw();},setLabels:l=>{labels=l;draw();},setReducedMotion(){},setMotion(){},setPaused(){},resize(){},destroy:()=>host.remove(),getState:()=>({mode:'fallback',phase,theme})};}
function mountScene(containerId){const placeholder=$('#'+containerId);if(!placeholder)return;if(sceneId===containerId&&sceneNode){if(placeholder!==sceneNode)placeholder.replaceWith(sceneNode);syncScene();return;}destroyScene();sceneId=containerId;sceneNode=placeholder;const mount=()=>{if(!sceneNode?.isConnected||sceneId!==containerId||!window.YV3D)return;cell?.destroy();cell=window.YV3D.mount(sceneNode,{phase:activePhase,theme:document.documentElement.dataset.theme,reduceMotion:reducedSceneMotion(),autoRotate:!paused,labels:sceneLabels()});syncScene();};if(window.YV3D)mount();else{cell=fallbackScene(sceneNode);sceneReadyHandler=()=>{sceneReadyHandler=null;mount();};window.addEventListener('yv3d:ready',sceneReadyHandler,{once:true});}}
function afterRender(a){init(a);const target=wantedSceneId();if(target)mountScene(target);else if(sceneNode)destroyScene();if(api.route()==='builder'&&ui.tab==='assemble'){requestAnimationFrame(drawEdges);if('ResizeObserver' in window){resizeObs=new ResizeObserver(drawEdges);if($('#workflow-canvas'))resizeObs.observe($('#workflow-canvas'));}}updateBadge();}
function beforeRender(){resizeObs?.disconnect();resizeObs=null;const next=wantedSceneId();if(sceneNode&&next===sceneId){cell?.setPaused?.(true);sceneNode.remove();}else destroyScene();}
function updateBadge(){document.querySelectorAll('[data-plan-count]').forEach(el=>el.textContent=plan?.stages.length||0);}
function toolButton(toolId){return `<label class="plan-tool-check"><input type="checkbox" data-plan-tool="${e(toolId)}" ${plan?.tools.includes(toolId)?'checked':''}><span>${b(plan?.tools.includes(toolId)?'included':'add')}</span></label>`;}
function toolPanel(toolId){const tool=api.maps().tool.get(toolId);if(!tool)return '';return `<section class="tool-plan-panel"><div class="section-head"><h3>${b('builder')}</h3>${toolButton(toolId)}</div><p>${b('parameterHint')}</p><details><summary>${b('parameters')} · ${tool.parameters.length}</summary>${tool.parameters.map(p=>`<label class="parameter-override"><code>${e(p.name)}</code><input type="text" data-plan-param="${e(p.name)}" data-tool-id="${toolId}" value="${e(plan?.parameters[toolId]?.[p.name]||'')}" placeholder="${e(b('unconfirmed'))}" maxlength="2000"></label>`).join('')}</details><a href="#builder" class="text-link">${b('continue')} →</a></section>`;}
function markerBar(){return `<div class="marker-plan-bar"><span>${api.icon('workflow')}<strong>${b('builder')}</strong></span><p>${b('assignmentHelp')}</p><a href="#builder?tab=studio" class="btn btn-small btn-primary">${b('studio')} <b>${plan?.markers.length||0}</b> →</a></div>`;}
function exported(){const c=window.YV_EXPORT_LAYOUT?.context(),data=api.data(),tools=plan.tools.map(id=>api.maps().tool.get(id)).filter(Boolean).map(t=>window.YV_INPUTS.toolContext(plan,t,data)),steps=plan.stages.map(id=>api.maps().step.get(id)).filter(Boolean),metrics=plan.metrics.map(id=>api.maps().metric.get(id)).filter(Boolean),projects=(plan.projects||[]).map(id=>projectCatalog().find(x=>x.id===id)).filter(Boolean),formulaIds=[...new Set(steps.flatMap(x=>x.formulaIds))];const clean=o=>{const{_search,...r}=o;return r;};const result={...plan,markerPanels:{include:plan.markers.filter(m=>m.role==='include').map(m=>m.id),control:plan.markers.filter(m=>m.role==='control').map(m=>m.id),exclude:plan.markers.filter(m=>m.role==='exclude').map(m=>m.id)},extensions:{lab:window.YV_LAB?.hasContent?.()?window.YV_LAB.exportData({enabledOnly:true}):null},exported:new Date().toISOString(),language:c?.language||api.prefs().language,exportSettings:window.YV_EXPORT_LAYOUT?.options(),kind:'research-plan-not-execution',provenance:{site:'YeastVar1011',catalogUpdated:data.workflow.updated,scope:c?.b('planningOnly')||b('planningOnly')},review:{recommendedStages:missingStages(),unconfirmedInputs:neededInputs(),...inputReview(),markers:window.YV_MARKERS?.review?.(plan)||null},analysisFramework:data.projects.analysisFramework||[],resultSpecificationRecords:(data.projects.resultSpecifications||[]).filter(s=>(plan.resultSpecificationIds||[]).includes(s.id)),projectRecords:projects.map(clean),stageRecords:steps.map(clean),toolRecords:tools.map(clean),metricRecords:metrics.map(clean),formulaRecords:formulaIds.map(id=>api.maps().formula.get(id)).filter(Boolean).map(clean),markerRecords:plan.markers.map(m=>({assignment:m,reference:clean(api.maps().marker.get(m.id))})),sourceUrls:[],references:[]};const selection=window.YV_MARKER_SELECTION;result.citationSelection=selection.citationSelection({tools:result.tools,baseURLs:selection.referenceLinks([result.resultSpecificationRecords,result.projectRecords,result.stageRecords,result.toolRecords,result.metricRecords,result.formulaRecords,result.extensions.lab]),markerRecords:result.markerRecords,sourceMap:api.maps().source});result.sourceUrls=[...result.citationSelection.sourceUrls];result.references=[...result.sourceUrls];if(window.YV_CITATIONS){const citations=window.YV_CITATIONS.build(result,data.literature);result.bibliography={style:'APA 7',entries:citations.entries,csl:citations.csl,unresolvedURLs:citations.unresolvedURLs,stats:citations.stats};}return result;}
function mermaid(){const c=window.YV_EXPORT_LAYOUT.context(),clean=s=>String(s).replace(/["\[\]\r\n]/g,' ').replace(/&/g,'&amp;'),font=window.YV_EXPORT_LAYOUT.fonts[window.YV_EXPORT_LAYOUT.options().font].css;return '---\nconfig:\n  theme: base\n  themeVariables:\n    fontFamily: '+JSON.stringify(font)+'\n    primaryColor: "#f7f8fa"\n    primaryTextColor: "#203c53"\n    primaryBorderColor: "#c8d5df"\n    lineColor: "#8194a5"\n---\nflowchart TD\n  accTitle: '+clean(plan.title)+'\n  accDescr: '+clean(c.text('flowHint'))+'\n'+plan.stages.map((id,i)=>`  ${id}["${i+1}. ${clean(c.field('steps',api.maps().step.get(id),'title'))}"]`).join('\n')+'\n'+plan.edges.filter(e=>plan.stages.includes(e.from)&&plan.stages.includes(e.to)).map(e=>`  ${e.from} --> ${e.to}`).join('\n');}
function markdown(){const c=window.YV_EXPORT_LAYOUT.context(),b=c.b,tt=c.t,tx=c.tx,inputLabel=c.input,stepTitle=id=>c.field('steps',api.maps().step.get(id),'title'),groupLabel=c.mk,x=exported(),t=c.tx,cit=window.YV_CITATIONS?.build(x,api.data().literature),cite=urls=>cit?.cite(urls,{html:false})||'';return `# ${plan.title}\n\n${b('planningOnly')}\n\n## ${b('objective')}\n\n${plan.objective||b('unconfirmed')}\n\n## ${b('available')}\n\n${plan.availableData.map(k=>'- '+inputLabel(k)).join('\n')}\n\n## ${b('workflowPreview')}\n\n\x60\x60\x60mermaid\n${mermaid()}\n\x60\x60\x60\n\n`+x.stageRecords.map((s,i)=>`## ${i+1}. ${stepTitle(s.id)}\n\n${c.field('steps',s,'purpose')}\n\n**${tt('inputs')}**\n\n${s.inputs.map(z=>'- '+t(z)).join('\n')}\n\n**${tt('outputs')}**\n\n${s.outputs.map(z=>'- '+t(z)).join('\n')}\n\n**${tt('metrics')}**\n\n${x.metricRecords.filter(m=>m.stepId===s.id).map(m=>`- ${c.field('metrics',m,'name')}: ${c.field('metrics',m,'definition')} (${tt('denominator')}: ${t(m.denominator)})`).join('\n')}\n\n**${tt('tools')}**\n\n${x.toolRecords.filter(z=>z.steps.includes(s.id)).map(z=>`### ${z.name} ${cit?.forTool(z.id,{html:false})||cite(z.sourceUrls)}\n\n${c.field('tools',z,'task')}\n\n${z.url}\n\n\x60\x60\x60text\n${z.entrypoint}\n\x60\x60\x60\n\n${z.parameters.map(p=>`- \x60${p.name}\x60 — ${t(p.meaning)}; ${t(p.selection)}. ${b('parameters')}: ${plan.parameters[z.id]?.[p.name]||b('unconfirmed')}`).join('\n')}\n\n${z.limitations.map(l=>'- '+t(l)).join('\n')}`).join('\n\n')}\n\n`).join('')+`## ${b('chosenMarkers')}\n\n${b('assignmentHelp')}\n\n${x.markerRecords.map(({assignment:a,reference:m})=>`- **${m.symbol}** (${m.systematic}): ${a.groups.map(groupLabel).join(', ')}; ${b('purpose')}: ${(a.purposes||[a.purpose]).map(b).join(', ')}; ${c.assignment(a)}; ${window.YV_MARKER_SELECTION.resolve(m,a).mode==='record'?c.mk('selectedEvidencePhases'):b('phaseRNA')}: ${(window.YV_MARKER_SELECTION.resolve(m,a).mode==='record'?window.YV_MARKER_SELECTION.resolve(m,a).phases:m.phases).join(', ')||'—'}; ${c.mk('selectedEvidence')}: ${window.YV_MARKER_SELECTION.resolve(m,a).records.length} ${cite(window.YV_MARKER_SELECTION.referenceURLs(m,a,api.maps().source))}`).join('\n')}\n\n## ${tt('formulas')}\n\n${x.formulaRecords.map(f=>`### ${c.field('formulas',f,'name')}\n\n${f.expression}\n\n${f.variables.map(v=>'- '+v.symbol+': '+t(v.meaning)).join('\n')}\n\n${f.assumptions.map(a=>'- '+t(a)).join('\n')}\n\n${f.sourceUrl}`).join('\n\n')}\n\n## ${b('requiredData')}\n\n${x.review.inputs.map(r=>'- '+inputLabel(r.id)+': '+b(r.status)+(r.dependencies.length?' — '+tt('inputs')+': '+r.dependencies.map(inputLabel).join(', '):'')).join('\n')}\n\n${x.review.rules.map(r=>'- '+tx(r.text)).join('\n')}\n\n${window.YV_PLAN_PREVIEW?.markdown(x)||''}## ${tt('references')}\n\n${cit?cit.bibliographyText+'\n\n'+(cit.unresolvedURLs.length?'### '+tt('sources')+'\n\n'+cit.unresolvedURLs.map(u=>'- '+u).join('\n'):''):x.references.map((u,i)=>`${i+1}. ${u}`).join('\n')}`;}
