function rerenderPicker(){if($('#picker-results'))$('#picker-results').innerHTML=pickerResults();}
document.addEventListener('change',async ev=>{if(!api)return;const el=ev.target;if(el.dataset.planField){updateField(el);editSession=null;}else if(el.dataset.inventory)mutate(()=>{const previousRoute=window.YV_INPUTS.route?.(plan);plan.availableData=el.checked?[...new Set([...plan.availableData,el.dataset.inventory])]:plan.availableData.filter(x=>x!==el.dataset.inventory);if((plan.inputRoute||'auto')==='auto'&&previousRoute!==window.YV_INPUTS.route?.(plan))window.YV_INPUTS.applyRoute?.(plan,'auto',api.data());});else if(el.dataset.planStage)toggleStage(el.dataset.planStage,el.checked);else if(el.dataset.planTool){toggleTool(el.dataset.planTool,el.checked);if(api.route()==='builder')api.render();else{el.closest('.plan-tool-check')?.querySelector('span')?.replaceChildren(document.createTextNode(b(el.checked?'included':'add')));updateBadge();}}else if(el.dataset.planMetric){toggleMetric(el.dataset.planMetric,el.checked);if(api.route()==='builder')api.render();}else if(el.dataset.studioMarker){if(el.checked){setMarker(el.dataset.studioMarker,true,ui.destination);}else setMarker(el.dataset.studioMarker,false);updateStudio();}else if(el.dataset.markerPurpose)mutate(()=>{const m=plan.markers.find(x=>x.id===el.dataset.markerPurpose);if(m){m.purpose=el.value;m.purposes=[el.value,...(m.purposes||[]).filter(p=>p!==el.value)]}});else if(el.id==='marker-purpose')ui.purpose=el.value;else if(el.id==='marker-destination')ui.destination=el.value;else if(el.id==='studio-only-chosen'){ui.onlyChosen=el.checked;updateStudio();}else if(el.dataset.planParam){updateField(el);editSession=null;}else if(el.id==='plan-import'){const f=el.files?.[0];if(!f)return;try{if(f.size>20e6)throw Error('size');const parsed=JSON.parse(await f.text());importPlan(parsed);api.toast(b('importSuccess'));}catch{api.toast(window.YV_RECOVERY?.text('importFailed')||b('importFailed'));}finally{el.value='';}}});
document.addEventListener('input',ev=>{if(!api)return;if(ev.target.dataset.planField||ev.target.dataset.planParam){updateField(ev.target);}else if(ev.target.id==='studio-marker-query'){ui.markerQ=ev.target.value;ui.markerLimit=150;updateStudio();}else if(ev.target.id==='plan-tool-search'){ui.query=ev.target.value;rerenderPicker();}});
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-build]');if(!el||!api)return;const act=el.dataset.build;if(act==='tab'&&el.dataset.value!=='assemble'){location.hash='#workbench?stage='+({studio:'annotation',review:'review'}[el.dataset.value]||'scope');return;}if(act==='next'&&ui.tab==='assemble'){location.hash='#workbench?stage=review';return;}if(act==='tab'){ui.tab=el.dataset.value;api.render();}else if(act==='next'){ui.tab=['scope','studio','assemble','review'][['scope','studio','assemble','review'].indexOf(ui.tab)+1]||'review';api.render();window.scrollTo({top:0,behavior:api.prefs().reducedMotion?'auto':'smooth'});}else if(act==='preset'){applyPreset(el.dataset.value);api.toast(window.YV_RECOVERY?.text(saveState.status==='saved'?'saved':'unsaved')||b('planSaved'));}else if(act==='undo'){undo();}else if(act==='redo'){redo();}else if(act==='more-markers'){ui.markerLimit+=150;updateStudio();}else if(act==='phase'){ui.markerLimit=150;activePhase=el.dataset.value;ui.destination=activePhase;updateStudio();}else if(act==='rotate'){paused=!paused;cell?.setPaused(paused);document.querySelectorAll('[data-build="rotate"]').forEach(x=>{x.title=b(paused?'resume':'pause');x.setAttribute('aria-label',x.title);x.classList.toggle('paused',paused)});}else if(act==='marker-info')api.openRecord('marker',el.dataset.id);else if(act==='tool-info')api.openRecord('tool',el.dataset.id);else if(act==='remove-group')mutate(()=>{const m=plan.markers.find(x=>x.id===el.dataset.id);m.groups=m.groups.filter(x=>x!==el.dataset.group);if(!m.groups.length)m.groups=['unassigned'];});else if(act==='focus-stage'){ui.stage=el.dataset.id;ui.query='';api.render();}else if(act==='tool-tab'){ui.toolTab=el.dataset.value;ui.query='';api.render();}else if(act==='move'){mutate(()=>{const i=plan.stages.indexOf(el.dataset.id),j=i+Number(el.dataset.direction);if(j>=0&&j<plan.stages.length)[plan.stages[i],plan.stages[j]]=[plan.stages[j],plan.stages[i]]});}else if(act==='output'){ui.connectFrom=el.dataset.id;api.render();}else if(act==='input'){if(ui.connectFrom&&ui.connectFrom!==el.dataset.id){const edge={from:ui.connectFrom,to:el.dataset.id};if(hasCycle([...plan.edges,edge]))api.toast(b('cycleBlocked'));else mutate(()=>{if(!plan.edges.some(x=>x.from===edge.from&&x.to===edge.to))plan.edges.push(edge);ui.connectFrom=null;});}}else if(act==='cancel-connect'){ui.connectFrom=null;api.render();}else if(act==='remove-edge')mutate(()=>plan.edges.splice(Number(el.dataset.index),1));else if(act==='auto-connect')mutate(()=>{plan.edges=plan.stages.slice(1).map((s,i)=>({from:plan.stages[i],to:s}));ui.connectFrom=null;});else if(act==='repair')mutate(()=>{plan.stages=prerequisiteClosure();plan.metrics=[...new Set([...plan.metrics,...plan.stages.flatMap(s=>api.maps().step.get(s).metricIds)])]});else if(act==='import')$('#plan-import').click();else if(act==='export-json')api.download('yeastvar1011-research-plan.json',JSON.stringify(exported(),null,2));else if(act==='export-md')api.download('yeastvar1011-research-plan.md',markdown(),'text/markdown;charset=utf-8');else if(act==='export-mermaid')api.download('yeastvar1011-workflow.mmd',mermaid(),'text/plain;charset=utf-8');else if(act==='export-svg')api.download('yeastvar1011-workflow.svg',svgExport(),'image/svg+xml;charset=utf-8');});
document.addEventListener('focusout',ev=>{if(ev.target.dataset.planField||ev.target.dataset.planParam)editSession=null;});
