document.addEventListener('dragstart',ev=>{const m=ev.target.closest('[data-drag-marker]'),s=ev.target.closest('[data-drag-stage]'),t=ev.target.closest('[data-drag-tool]');if(m)ev.dataTransfer.setData('application/x-yv-marker',m.dataset.dragMarker);else if(s)ev.dataTransfer.setData('application/x-yv-stage',s.dataset.dragStage);else if(t)ev.dataTransfer.setData('application/x-yv-tool',t.dataset.dragTool);else return;ev.dataTransfer.effectAllowed='copyMove';ev.target.classList.add('dragging');});
document.addEventListener('dragend',()=>document.querySelectorAll('.dragging,.drag-over').forEach(el=>el.classList.remove('dragging','drag-over')));
